# ─────────────────────────────────────
# v3.9 — 소재 키워드 (장르가 아님)
# ─────────────────────────────────────
# 환생·회귀·빙의 등은 '소재/설정'이지 장르가 아니다.
# 장르 판정에서 제외한다. (예: "로맨틱 코미디/환생" → 코미디 + 로맨스)
TROPE_KEYWORDS = [
    "환생", "회귀", "빙의", "타임슬립", "차원이동", "각성",
    "학원", "학원물", "오피스", "사내", "계약결혼", "재벌",
]


def detect_tropes(genre_str):
    """장르 문자열에서 소재 키워드를 추출한다. (v3.9)"""
    if not genre_str:
        return []
    gl = str(genre_str).lower()
    return [t for t in TROPE_KEYWORDS if t in gl]


# ─────────────────────────────────────
# v3.9 — 장르 우선순위 (위협·긴장 담당 장르가 상위)
# ─────────────────────────────────────
# 복합 장르에서 어느 쪽이 오프닝 DNA와 사건 성격을 결정하는지 정한다.
# M2 원칙: "독자를 붙잡는 것은 안온함이 아니라 불안이다."
# 숫자가 작을수록 우선.
GENRE_PRIORITY = {
    "호러/공포": 1,
    "범죄/스릴러": 2,
    "미스터리": 3,
    "액션": 4,
    "무협": 5,
    "SF": 6,
    "판타지": 7,
    "역사": 8,
    "로맨스": 9,
    "코미디": 10,
    "드라마": 11,
    "미지정": 99,
}


_ROMCOM_PAT = ("로맨틱 코미디", "로맨틱코미디", "로코", "rom-com", "romcom")


def detect_genre_keys(genre_str):
    """장르 문자열에서 해당하는 모든 장르 키를 우선순위 순으로 반환. (v3.9)

    복합 장르를 하나로 뭉개지 않는다.
    예) "로맨틱 스릴러" → ["범죄/스릴러", "로맨스"]
        "판타지 로맨스" → ["판타지", "로맨스"]
        "무협 학원물"   → ["무협"]
    첫 번째가 주 장르(오프닝 DNA·사건 성격 결정), 나머지는 보조 장르.
    """
    if not genre_str:
        return ["미지정"]
    gl = str(genre_str).lower()
    found = []
    for kws, gk in GENRE_KEYWORD_MAP:
        if gk in found:
            continue
        if any(k in gl for k in kws):
            found.append(gk)
    if not found:
        return ["미지정"]
    found.sort(key=lambda g: GENRE_PRIORITY.get(g, 50))
    # 로맨틱 코미디는 코미디가 주도한다 (예외 처리)
    if any(p in gl for p in _ROMCOM_PAT) and "코미디" in found:
        found.remove("코미디")
        found.insert(0, "코미디")
    return found


def detect_genre_key(genre_str):
    """주 장르 하나를 반환. (하위 호환 유지)"""
    return detect_genre_keys(genre_str)[0]


def get_genre_rules_block(genre_key):
    r = GENRE_RULES.get(genre_key, GENRE_RULES["미지정"])
    ml = "\n".join([f"  - {m}" for m in r["must_have"]])
    fl = "\n".join([f"  - {f}" for f in r["fails"]])
    return f"""[장르 Rule Pack: {genre_key}]
핵심 원칙: {r['core']}
장르적 재미의 본질: {r['genre_fun']}
오프닝 패턴: {r['opening']}
필수 요소:
{ml}
Hook 규칙: {r['hook_rule']}
Punch 규칙: {r['punch_rule']}
금지 사항: {r['forbidden']}
장르 실패 패턴:
{fl}
"""

